import{_ as r,o as t,c as a,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月12日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-12.md","filePath":"science-log/src/reconstructed/2026-07-12.md"}'),n={name:"science-log/src/reconstructed/2026-07-12.md"};function s(i,e,l,g,u,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年7月12日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月12日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月12日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月12日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-07-12 为<strong>周日</strong>。CrossRef 当日命中：Nature（0028-0836）<strong>0 条</strong>、Science 系（10.1126）<strong>0 条</strong>、PNAS（0027-8424）<strong>0 条</strong>——三大刊当日均无刊出。故科学 5 篇取自最近的出版窗口 <strong>2026-07-08 ~ 2026-07-10</strong>，逐条标注实际出版日；AI 5 篇取自 arXiv cs.AI 当日投稿（30 条命中，实际取用）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607120000 TO 202607122359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🌍-lares-2-把地球参考系拖曳测到千分之一精度" tabindex="-1">🌍 LARES-2 把地球参考系拖曳测到千分之一精度 <a class="header-anchor" href="#🌍-lares-2-把地球参考系拖曳测到千分之一精度" aria-label="Permalink to &quot;🌍 LARES-2 把地球参考系拖曳测到千分之一精度&quot;">​</a></h3><p><strong>LARES-2 satellite measures frame-dragging effect around the Earth</strong><em>Nature（2026-07-08）</em></p><p>广义相对论预言：旋转质量会拖曳周围的时空（Lense–Thirring 效应）。团队用 2022 年发射的激光相对论卫星 LARES-2（表面积/质量比极低、后向反射器分布高度均匀、轨道经过优化）联合老前辈 LAGEOS 与 GRACE 卫星做激光测距，把地球参考系拖曳的<strong>相对不确定度压到千分之一量级</strong>，比此前太阳系内的测定好一个数量级。这既是对近地环境广义相对论的严格确认，也对预测&quot;参考系拖曳异常&quot;的替代引力理论（包括 Chern-Simons 标量-张量扩展）构成强约束；副产品是日月潮汐测定同步改善。作者名单里有 Roger Penrose 与 V. Gurzadyan。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10715-0" target="_blank" rel="noreferrer">10.1038/s41586-026-10715-0</a></p><h3 id="🧫-通用细胞嵌入-细胞生物学的-基础模型" tabindex="-1">🧫 通用细胞嵌入：细胞生物学的&quot;基础模型&quot; <a class="header-anchor" href="#🧫-通用细胞嵌入-细胞生物学的-基础模型" aria-label="Permalink to &quot;🧫 通用细胞嵌入：细胞生物学的&quot;基础模型&quot;&quot;">​</a></h3><p><strong>Universal cell embedding provides a foundation model for cell biology</strong><em>Nature（2026-07-08）</em></p><p>斯坦福的 Yusuf Roohani、Jure Leskovec、Stephen Quake 等提出 UCE（universal cell embedding）：以自监督方式在大量单细胞数据语料上训练，学出一个跨组织、跨物种的统一生物潜空间。最大卖点是&quot;零标注、零微调&quot;——新细胞可直接嵌入。团队用它构建了整合巨型图谱：<strong>3600 万个细胞、1000 多个具名细胞类型、数百个实验、数十种组织、8 个物种</strong>。潜空间出现涌现行为：能识别训练中从未涉及的发育谱系，也能嵌入训练集之外的物种。这意味着细胞的表征正在从&quot;每个数据集一套 embedding&quot;走向&quot;一个坐标系统管所有细胞&quot;。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10689-z" target="_blank" rel="noreferrer">10.1038/s41586-026-10689-z</a></p><h3 id="☀️-无铟钙钛矿-硅叠层电池-33-6-与-207-9-cm2-组件-31-0" tabindex="-1">☀️ 无铟钙钛矿/硅叠层电池：33.6% 与 207.9 cm² 组件 31.0% <a class="header-anchor" href="#☀️-无铟钙钛矿-硅叠层电池-33-6-与-207-9-cm2-组件-31-0" aria-label="Permalink to &quot;☀️ 无铟钙钛矿/硅叠层电池：33.6% 与 207.9 cm² 组件 31.0%&quot;">​</a></h3><p><strong>Indium-free perovskite/silicon tandem solar cells with tin oxide recombination layer and electrodes</strong><em>Science（2026-07-09）</em></p><p>铟基透明导电氧化物是叠层电池的标配电极与复合层，但铟稀缺、溅射又会损伤钙钛矿。中国团队改用反应等离子体沉积的 SnOₓ（RPD-SnOₓ）：作复合层时认证效率 <strong>33.6%</strong>；作复合层+电极的&quot;全无铟&quot;器件冠军效率 <strong>33.2%（1 cm²）</strong>，迷你组件认证 <strong>31.0%（207.9 cm²）</strong>。致密均匀的 SAM 锚定抑制了非辐射复合与卤素迁移；无铟组件通过热、湿热与户外工况稳定性测试，户外运行 105 天后仍保持初始最高效率的 65%。这条路线把&quot;效率纪录&quot;与&quot;材料供应安全&quot;同时解决，是叠层走向吉瓦级的关键一步。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aef5355" target="_blank" rel="noreferrer">10.1126/science.aef5355</a></p><h3 id="🌊-定向海洋云增白会削弱随后的厄尔尼诺" tabindex="-1">🌊 定向海洋云增白会削弱随后的厄尔尼诺 <a class="header-anchor" href="#🌊-定向海洋云增白会削弱随后的厄尔尼诺" aria-label="Permalink to &quot;🌊 定向海洋云增白会削弱随后的厄尔尼诺&quot;">​</a></h3><p><strong>Targeted marine cloud brightening weakens subsequent El Niño</strong><em>Science Advances（2026-07-10）</em></p><p>海洋云增白（MCB）通常被当作&quot;降长期升温&quot;的太阳能地球工程方案，本文转而问：能不能<strong>定向调节季节—年际变率</strong>？作者借 2019–2020 澳大利亚山火这场&quot;天然实验&quot;（野火气溶胶造成的云增白与类拉尼娜响应）做模型复现，再在东南太平洋模拟 MCB 干预 1997–98 与 2015–16 两次强厄尔尼诺：在厄尔尼诺增长期启动，能打断放大它的 Bjerknes 正反馈；但干预一旦停止，效果随之衰减——只有<strong>最早、最长</strong>的干预才能把 ENSO 拉回中性并削弱遥相关。代价是可能出现&quot;厄尔尼诺被削弱后紧跟一个更早的拉尼娜&quot;的意外后果。结论不是&quot;该做&quot;，而是&quot;变率与遥相关必须被列为地球工程的研究目标与风险评估项&quot;。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.adx3012" target="_blank" rel="noreferrer">10.1126/sciadv.adx3012</a></p><h3 id="🤖-带-具身记忆与逻辑-的胶囊机器人" tabindex="-1">🤖 带&quot;具身记忆与逻辑&quot;的胶囊机器人 <a class="header-anchor" href="#🤖-带-具身记忆与逻辑-的胶囊机器人" aria-label="Permalink to &quot;🤖 带&quot;具身记忆与逻辑&quot;的胶囊机器人&quot;">​</a></h3><p><strong>Physically intelligent capsule robots with embodied memory and logic in the gastrointestinal tract</strong><em>PNAS（2026-07-08）</em></p><p>可吞服机器人在尺寸、供电、生物安全三重约束下，很难同时做到&quot;感知—决策—执行&quot;。Metin Sitti 团队（Koç University／Max Planck 体系）与香港中文大学合作提出 PI Capbots，思路是<strong>把计算卸载给材料</strong>：多稳态超材料把腔内压力编码成机械记忆，可编程水凝胶实现正交传感与逻辑运算，螺旋纤维负责多模态运动——不需要中央电子控制，就能把冗余的生理信号压缩成少量&quot;事件触发&quot;输出。大动物模型（离体+活体）验证了有效性与可重复性。这是&quot;物理智能&quot;（physical intelligence）从概念走向可植入器件的实证。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2605060123" target="_blank" rel="noreferrer">10.1073/pnas.2605060123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🌀-奇点空间-用复平面极点—留数表示信号的扩散模型" tabindex="-1">🌀 奇点空间：用复平面极点—留数表示信号的扩散模型 <a class="header-anchor" href="#🌀-奇点空间-用复平面极点—留数表示信号的扩散模型" aria-label="Permalink to &quot;🌀 奇点空间：用复平面极点—留数表示信号的扩散模型&quot;">​</a></h3><p><strong>The Singularity Space: A Generative Diffusion Framework for Signal Representation</strong><em>arXiv（2026-07-12）</em></p><p>生成模型习惯把信号表示为稠密振幅网格，代价是抹平对物理正确性至关重要的尖锐瞬变。Bar-Yosef、Averbuch、Turkel 回到亚纯函数的<strong>极点—留数</strong>经典表示，学一个&quot;每信号一组复平面奇点坐标&quot;的受物理约束潜空间，再用 transformer 扩散模型直接在奇点坐标上采样（采样时施加几何约束）。在 1D Burgers 激波上：每条激波用 <strong>32 个奇点</strong>表示（相对 1024 点网格压缩 8 倍）；TV 比 ≈ 1，说明结构在未见噪声下得以保持；零样本亚分辨率泛化误差比网格基线低 <strong>4.2 倍</strong>；分布内物理参数恢复到 10⁻⁴ 绝对误差。三条性质——可解释、结构稳定（抑制 Gibbs 振铃）、无分辨率输出——正对准了&quot;用正确的基函数表示物理&quot;这条老路。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.10930" target="_blank" rel="noreferrer">2607.10930</a></p><h3 id="📉-rlvr-会缩小推理边界-pass-k-反转的诊断" tabindex="-1">📉 RLVR 会缩小推理边界：pass@k 反转的诊断 <a class="header-anchor" href="#📉-rlvr-会缩小推理边界-pass-k-反转的诊断" aria-label="Permalink to &quot;📉 RLVR 会缩小推理边界：pass@k 反转的诊断&quot;">​</a></h3><p><strong>When RLVR Shrinks the Reasoning Boundary: Diagnosing Pass@k Inversion</strong><em>arXiv（2026-07-12）</em></p><p>可验证奖励强化学习（RLVR）能提高单次采样准确率，却可能在多次采样下变差：训练后的策略在<strong>大 k 时能解出的不同题目反而比基座模型更少</strong>。作者把这种 pass@k 反转定位到&quot;边界题&quot;——基座模型里存在稀少但可被采样捞到的正确轨迹，因为太稀疏而在有限 rollout 组里采不到，于是&quot;证据缺席&quot;，RLVR 从未强化它们，反而在优化中把它们抹掉。提出的 PBA（Per-Problem Base Anchoring）是个刻意简单的证明：对有足够冻结基座正确证据的提示做锐化，对高风险提示锚回基座分布。三个随机种子在 Omni-MATH-Test 上同时提升 pass@1 与大预算覆盖率；3000 提示的 regime 对照研究复现了签名。核心主张是：后训练不只该决定&quot;优化多强&quot;，还该决定&quot;哪些提示可以优化&quot;。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.20543" target="_blank" rel="noreferrer">2607.20543</a></p><h3 id="🛡️-纠缠之墙-激活空间探针是风险探测器-不是情境裁判" tabindex="-1">🛡️ 纠缠之墙：激活空间探针是风险探测器，不是情境裁判 <a class="header-anchor" href="#🛡️-纠缠之墙-激活空间探针是风险探测器-不是情境裁判" aria-label="Permalink to &quot;🛡️ 纠缠之墙：激活空间探针是风险探测器，不是情境裁判&quot;">​</a></h3><p><strong>The Entanglement Wall: Activation-Space Probes as Risk Detectors, Not Context Adjudicators</strong><em>arXiv（2026-07-12）</em></p><p>基于激活的安全闸门必须区分&quot;有害协助&quot;与&quot;同一话题上的正当工作&quot;。作者把 5 个 checkpoint 特定的读出及其原始阈值，原封不动迁移到 4 组建模配对队列（共 450 对，人工核对话题与请求框架相似度）：在 Twin-70 主队列上，有害与无害的分数区间<strong>直接重叠</strong>，AUROC 从源任务的 0.996–0.999 掉到 0.701–0.860；配对排序仍有 0.829–0.929，但迁移阈值会检出 0.943–1.000 的有害请求，同时<strong>误拦 0.686–0.986 的配对无害请求</strong>。即便在按对分组的交叉验证里重拟合阈值，平衡阈值误差仍达 0.229–0.329。换成 logistic/RBF/浅层 MLP 探针只降低误拦、检出率跌到 0.200–0.671。结论：这些源工作点无法同时兼顾&quot;强检出&quot;与&quot;同话题正当访问&quot;——风险排序可用，可用决策边界不存在。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.13075" target="_blank" rel="noreferrer">2607.13075</a></p><h3 id="💻-seta-为终端智能体扩张可验证环境" tabindex="-1">💻 SETA：为终端智能体扩张可验证环境 <a class="header-anchor" href="#💻-seta-为终端智能体扩张可验证环境" aria-label="Permalink to &quot;💻 SETA：为终端智能体扩张可验证环境&quot;">​</a></h3><p><strong>SETA: Scaling Environments for Terminal Agents</strong><em>arXiv（2026-07-12）</em></p><p>终端命令行是覆盖面最广的通用 agent 接口，但规模化训练一直卡在&quot;缺自然监督&quot;：要有多样且自洽的任务指令、可执行环境、可靠验证。SETA 用两条共享同一验证机制的流水线解决：SETA-Synth 把多种来源转成标准化 RL 环境，SETA-Evol 从已有环境自适应扩增难度与多样性。产出 SETA-Env——目前最大的开源可验证终端 RL 数据集，<strong>4500+ 环境</strong>。用 GRPO 训 Qwen3-8B，在 Terminal-Bench 2.0 上 pass 率 12%，是同规模 RL 训练模型的最好结果；在相同 harness 下 DeepSeek-V4-Flash 的 pass@1 从 40% 升到 43%、pass@5 从 54% 升到 58%。要点在于&quot;环境本身是可扩张的资产&quot;，而非又调了一版 reward。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.10891" target="_blank" rel="noreferrer">2607.10891</a></p><h3 id="🔬-imaging-101-把-llm-编码智能体拉进科学计算成像" tabindex="-1">🔬 Imaging-101：把 LLM 编码智能体拉进科学计算成像 <a class="header-anchor" href="#🔬-imaging-101-把-llm-编码智能体拉进科学计算成像" aria-label="Permalink to &quot;🔬 Imaging-101：把 LLM 编码智能体拉进科学计算成像&quot;">​</a></h3><p><strong>Imaging-101: Benchmarking LLM Coding Agents on Scientific Computational Imaging</strong><em>arXiv（2026-07-12）</em></p><p>计算成像从间接、含噪的测量里恢复隐藏信号，是跨学科定量发现的地基，但搭一条正确的重建流水线极其费力。Imaging-101 给出 <strong>57 个专家核验任务</strong>，覆盖 6 个科学域，每项锚定一篇同行评议论文，并规范化为四阶段流水线（预处理 → 前向物理建模 → 反演求解 → 可视化）；三条评测轨（规划、函数级单测、端到端重建）分别探不同能力。评测 7 个前沿 LLM 后暴露出通用编程基准测不到的系统性短板：算法选择、物理约定（归一化/单位/边界条件）处理、流水线集成。作者据此主张&quot;技能增强的领域专用 agent&quot;是通往可靠科学计算助手的现实路径。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.10789" target="_blank" rel="noreferrer">2607.10789</a></p><blockquote><p>📅 日期：2026-07-12 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const q=r(n,[["render",s]]);export{p as __pageData,q as default};
